CREATE TABLE sc_remote_write_guard(mount_id BIGINT NOT NULL PRIMARY KEY,active_operation VARCHAR(36),CONSTRAINT sc_remote_guard_mount_fk FOREIGN KEY(mount_id) REFERENCES sc_drive_mount(id));
CREATE TABLE sc_remote_write_operation(id VARCHAR(36) NOT NULL PRIMARY KEY,mount_id BIGINT NOT NULL,actor_id BIGINT NOT NULL,grant_root VARCHAR(1024) NOT NULL,target_path VARCHAR(4096) NOT NULL,object_key VARCHAR(4608) NOT NULL,is_directory BOOLEAN NOT NULL,config_version BIGINT NOT NULL,authorization_hash VARCHAR(64) NOT NULL,status VARCHAR(20) NOT NULL,reserved_bytes BIGINT NOT NULL,created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL,CONSTRAINT sc_remote_operation_mount_fk FOREIGN KEY(mount_id) REFERENCES sc_drive_mount(id));
CREATE INDEX sc_remote_operation_owner ON sc_remote_write_operation(actor_id,mount_id,created_at);
